tailwind:
/* Arbitrary value: exactly the CSS gradient, any Tailwind v4 project. */
bg-[linear-gradient(90deg,#ff0000_20%,#0000ff_80%)]

/* Native utilities (two or three stops). bg-linear-<angle> interpolates in OKLAB by default in Tailwind v4; the modifier pins the space. */
bg-linear-90/srgb from-[#ff0000] from-20% to-[#0000ff] to-80%

/* Theme variable: use as class "bg-gradient". */
@theme {
  --background-image-gradient: linear-gradient(90deg, #ff0000 20%, #0000ff 80%);
}

/* Custom utility: use as class "bg-gradient". */
@utility bg-gradient {
  background-image: linear-gradient(90deg, #ff0000 20%, #0000ff 80%);
}

css-variables:
:root {
  --gradient-angle: 90deg;
  --gradient-color-1: #ff0000;
  --gradient-position-1: 20%;
  --gradient-color-2: #0000ff;
  --gradient-position-2: 80%;
  --gradient: linear-gradient(var(--gradient-angle), var(--gradient-color-1) var(--gradient-position-1), var(--gradient-color-2) var(--gradient-position-2));
}

/* Usage: background: var(--gradient); */

